def match(orders):
    buy_book = []  # list of (price, arrival_time, id, qty)
    sell_book = []  # list of (price, arrival_time, id, qty)
    resting = {}  # id -> (side, price, qty, arrival_time)
    trades = []
    arrival_time = 0

    for order in orders:
        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in resting:
                side, price, qty, _ = resting[order_id]
                del resting[order_id]
                if side == 'buy':
                    buy_book = [(p, t, oid, q) for p, t, oid, q in buy_book if oid != order_id]
                else:
                    sell_book = [(p, t, oid, q) for p, t, oid, q in sell_book if oid != order_id]
            continue

        order_type = order[0]
        order_id = order[1]
        side = order[2]
        qty = order[3] if order_type == 'market' else order[4]
        price = None if order_type == 'market' else order[3]

        arrival_time += 1

        if side == 'buy':
            # Match against sell_book
            while qty > 0 and sell_book:
                if order_type == 'market':
                    # Match at any price
                    sell_price, sell_arrival, sell_id, sell_qty = sell_book[0]
                elif price < sell_book[0][0]:
                    # No more matches
                    break
                else:
                    if price < sell_book[0][0]:
                        break

                sell_price, sell_arrival, sell_id, sell_qty = sell_book[0]

                if order_type != 'market' and price < sell_price:
                    break

                trade_qty = min(qty, sell_qty)
                trades.append([order_id, sell_id, sell_price, trade_qty])

                qty -= trade_qty
                sell_qty -= trade_qty

                if sell_qty == 0:
                    sell_book.pop(0)
                    del resting[sell_id]
                else:
                    sell_book[0] = (sell_price, sell_arrival, sell_id, sell_qty)
                    resting[sell_id] = ('sell', sell_price, sell_qty, sell_arrival)

            # Rest remaining qty
            if qty > 0 and order_type in ['limit', 'ioc']:
                if order_type == 'limit':
                    buy_book.append((price, arrival_time, order_id, qty))
                    resting[order_id] = ('buy', price, qty, arrival_time)
            elif qty > 0 and order_type == 'market':
                pass  # market order remainder discarded

        else:  # side == 'sell'
            # Match against buy_book
            while qty > 0 and buy_book:
                if order_type == 'market':
                    # Match at any price
                    buy_price, buy_arrival, buy_id, buy_qty = buy_book[0]
                elif price > buy_book[0][0]:
                    # No more matches
                    break
                else:
                    if price > buy_book[0][0]:
                        break

                buy_price, buy_arrival, buy_id, buy_qty = buy_book[0]

                if order_type != 'market' and price > buy_price:
                    break

                trade_qty = min(qty, buy_qty)
                trades.append([buy_id, order_id, buy_price, trade_qty])

                qty -= trade_qty
                buy_qty -= trade_qty

                if buy_qty == 0:
                    buy_book.pop(0)
                    del resting[buy_id]
                else:
                    buy_book[0] = (buy_price, buy_arrival, buy_id, buy_qty)
                    resting[buy_id] = ('buy', buy_price, buy_qty, buy_arrival)

            # Rest remaining qty
            if qty > 0 and order_type in ['limit', 'ioc']:
                if order_type == 'limit':
                    sell_book.append((price, arrival_time, order_id, qty))
                    resting[order_id] = ('sell', price, qty, arrival_time)
            elif qty > 0 and order_type == 'market':
                pass  # market order remainder discarded

    return trades

